window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-99bc64fda0530c16"]={"versions": [{"id": "FIG-99bc64fda0530c16", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter des <code>SporadicEventTriggering</code> innerhalb des Teilmodells <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>EventTriggeringConstraint::SporadicEventTriggering</code> (Paketkontext oben rechts als kursives <code>EventTriggeringConstraint</code> annotiert), besitzt keine lokalen Attribute im sichtbaren Bereich.</li>\n<li>Klasse <code>MultidimensionalTime::MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime::MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für jedes <code>SporadicEventTriggering</code> zwingend genau eine <code>minimumInterArrivalTime</code> und genau eine <code>maximumInterArrivalTime</code> instanziieren (Kardinalität jeweils strikt 1). Jitter und Periode dürfen optional hinterlegt werden (0..1). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> sind ohne explizite Multiplizitätsklammer angegeben.</p>"}, {"id": "FIG-7d6a367aea55e0e7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter des <code>SporadicEventTriggering</code> innerhalb des Teilmodells <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>EventTriggeringConstraint::SporadicEventTriggering</code> (Paketkontext oben rechts als kursives <code>EventTriggeringConstraint</code> annotiert), besitzt keine lokalen Attribute im sichtbaren Bereich.</li>\n<li>Klasse <code>MultidimensionalTime::MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime::MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für jedes <code>SporadicEventTriggering</code> zwingend genau eine <code>minimumInterArrivalTime</code> und genau eine <code>maximumInterArrivalTime</code> instanziieren (Kardinalität jeweils strikt 1). Jitter und Periode dürfen optional hinterlegt werden (0..1). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> sind ohne explizite Multiplizitätsklammer angegeben.</p>"}, {"id": "FIG-8cd2a59aae01cc23", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter des <code>SporadicEventTriggering</code> innerhalb des Teilmodells <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>EventTriggeringConstraint::SporadicEventTriggering</code> (Paketkontext oben rechts als kursives <code>EventTriggeringConstraint</code> annotiert), besitzt keine lokalen Attribute im sichtbaren Bereich.</li>\n<li>Klasse <code>MultidimensionalTime::MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime::MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für jedes <code>SporadicEventTriggering</code> zwingend genau eine <code>minimumInterArrivalTime</code> und genau eine <code>maximumInterArrivalTime</code> instanziieren (Kardinalität jeweils strikt 1). Jitter und Periode dürfen optional hinterlegt werden (0..1). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> sind ohne explizite Multiplizitätsklammer angegeben.</p>"}, {"id": "FIG-00146e33b4a23dc5", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter des <code>SporadicEventTriggering</code> innerhalb des Teilmodells <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>EventTriggeringConstraint::SporadicEventTriggering</code> (Paketkontext oben rechts als kursives <code>EventTriggeringConstraint</code> annotiert), besitzt keine lokalen Attribute im sichtbaren Bereich.</li>\n<li>Klasse <code>MultidimensionalTime::MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType</code> und <code>+ cseCodeFactor: Integer</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime::MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler müssen für jedes <code>SporadicEventTriggering</code> zwingend genau eine <code>minimumInterArrivalTime</code> und genau eine <code>maximumInterArrivalTime</code> instanziieren (Kardinalität jeweils strikt 1). Jitter und Periode dürfen optional hinterlegt werden (0..1). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> sind ohne explizite Multiplizitätsklammer angegeben.</p>"}, {"id": "FIG-4a357904c0fe5826", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter der Klasse <code>SporadicEventTriggering</code> im Paketkontext <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>SporadicEventTriggering</code> (Paketkontext oben rechts kursiv als <code>EventTriggeringConstraint</code> ausgewiesen).</li>\n<li>Klasse <code>MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType [0..1]</code> und <code>+ cseCodeFactor: Integer [0..1]</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler können alle vier Zeitparameter (<code>jitter</code>, <code>minimumInterArrivalTime</code>, <code>maximumInterArrivalTime</code>, <code>period</code>) optional konfigurieren, da für sämtliche Kompositionsrollen eine Multiplizität von <code>0..1</code> gilt. In <code>MultidimensionalTime</code> sind auch die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> optional mit der Multiplizität <code>[0..1]</code> spezifiziert.</p>"}, {"id": "FIG-d2cd15f1ce7822af", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter der Klasse <code>SporadicEventTriggering</code> im Paketkontext <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>SporadicEventTriggering</code> (Paketkontext oben rechts kursiv als <code>EventTriggeringConstraint</code> ausgewiesen).</li>\n<li>Klasse <code>MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType [0..1]</code> und <code>+ cseCodeFactor: Integer [0..1]</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler können alle vier Zeitparameter (<code>jitter</code>, <code>minimumInterArrivalTime</code>, <code>maximumInterArrivalTime</code>, <code>period</code>) optional konfigurieren, da für sämtliche Kompositionsrollen eine Multiplizität von <code>0..1</code> gilt. In <code>MultidimensionalTime</code> sind auch die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> optional mit der Multiplizität <code>[0..1]</code> spezifiziert.</p>"}, {"id": "FIG-1b8efcf4fd34fbe8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt). Das Diagramm spezifiziert die strukturellen Eigenschaften und Zeitparameter der Klasse <code>SporadicEventTriggering</code> im Paketkontext <code>EventTriggeringConstraint</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Klasse <code>SporadicEventTriggering</code> (Paketkontext oben rechts kursiv als <code>EventTriggeringConstraint</code> ausgewiesen).</li>\n<li>Klasse <code>MultidimensionalTime</code> mit den Attributen <code>+ cseCode: CseCodeType [0..1]</code> und <code>+ cseCodeFactor: Integer [0..1]</code>.</li>\n<li>Vier Kompositionen (schwarze Raute an <code>SporadicEventTriggering</code>) zur Klasse <code>MultidimensionalTime</code>:</li>\n<li><code>+jitter</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+maximumInterArrivalTime</code> mit Multiplizität <code>0..1</code></li>\n<li><code>+period</code> mit Multiplizität <code>0..1</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Die Entität beschreibt die zeitlichen Schranken und Triggerbedingungen sporadischer Ereignisse über Referenzen auf dimensionierte Zeiteinheiten (Minimal- und Maximal-Interarrival-Zeiten als Pflichtwerte, Jitter und Periode optional).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler können alle vier Zeitparameter (<code>jitter</code>, <code>minimumInterArrivalTime</code>, <code>maximumInterArrivalTime</code>, <code>period</code>) optional konfigurieren, da für sämtliche Kompositionsrollen eine Multiplizität von <code>0..1</code> gilt. In <code>MultidimensionalTime</code> sind auch die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> optional mit der Multiplizität <code>[0..1]</code> spezifiziert.</p>"}], "trans": [{"from": "FIG-99bc64fda0530c16", "to": "FIG-7d6a367aea55e0e7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Hintergrundfarbe der Klassenboxen von Gelb auf Beige angepasst.</li>\n<li>Vertikaler Weißraum reduziert (Höhe verringert von 942 px auf 676 px).</li>\n<li>Typnotation der Attribute in <code>MultidimensionalTime</code> von Leerzeichen vor Doppelpunkt auf Leerzeichen nach Doppelpunkt umgestellt (<code>+ cseCode :CseCodeType</code>, <code>+ cseCodeFactor :Integer</code>).</li>\n</ul>"}, {"from": "FIG-7d6a367aea55e0e7", "to": "FIG-8cd2a59aae01cc23", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8cd2a59aae01cc23", "to": "FIG-00146e33b4a23dc5", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Typnotation der Attribute in <code>MultidimensionalTime</code> angepasst: Leerzeichen vor dem Doppelpunkt entfernt (<code>+ cseCode: CseCodeType</code>, <code>+ cseCodeFactor: Integer</code>).</li>\n</ul>"}, {"from": "FIG-00146e33b4a23dc5", "to": "FIG-4a357904c0fe5826", "fr": "R20-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalität der Rollen <code>minimumInterArrivalTime</code> und <code>maximumInterArrivalTime</code> von <code>1</code> auf <code>0..1</code> geändert.</li>\n<li>Kardinalität der Attribute <code>cseCode</code> und <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> explizit als <code>[0..1]</code> definiert.</li>\n<li>Paketpräfixe in den Klassennamen entfernt: <code>EventTriggeringConstraint::SporadicEventTriggering</code> zu <code>SporadicEventTriggering</code> sowie <code>MultidimensionalTime::MultidimensionalTime</code> zu <code>MultidimensionalTime</code>.</li>\n</ul>"}, {"from": "FIG-4a357904c0fe5826", "to": "FIG-d2cd15f1ce7822af", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d2cd15f1ce7822af", "to": "FIG-1b8efcf4fd34fbe8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
